      ...(k === 'flowMeterTemp' ? [onTab ? ['fp' + i, 'Temperature: Select Temperature Probe or None', 'sel', probes] : ['_t' + i, 'Temperature: Select Temperature Probe or None (picked when it is on a Tab)', 'note']] : []),
