  if (C.ports.in2) t.liquidPorts = String(t.liquidPorts || (t.ports?.in2?.installed ? 4 : 2));
  for (const [k, d] of Object.entries(C.ports)) { const q = t.ports?.[k]; t[k + '_on'] = q ? !!q.installed : !!d.on; t[k + '_pos'] = q?.position; t[k + '_fit'] = q?.fitting || ''; }
